def endOfMinute():
	"""Helper: now rounded up to the end of the minute, stable for 60 s."""
	millis = system.date.toMillis(system.date.now())
	return system.date.fromMillis(millis - millis % 60000 + 59999)

def set_time(date, hour, minute=0, second=0):
	"""Helper: set time on a date."""
	return system.date.setTime(date, hour, minute, second)

