	def set_time(date, hour):
		"""Helper: set hour on a date, minutes and seconds to 0."""
		return system.date.setTime(date, hour, 0, 0)

	year = system.date.getYear(value)
	month = system.date.getMonth(value)
	day = system.date.getDayOfMonth(value)
	hour = system.date.getHour24(value)

	dropDownPeriod = self.getChild("root").getChild("Filters").getChild("Dropdown Periodo").props.value
	shift = self.custom.shift  # 1, 2, or 3
	startTime = self.getChild("root").getChild("Filters").getChild("DateTimeInput_StartTime").props.value

	if dropDownPeriod == 7:  # Personalizado
		return startTime

	today = system.date.getDate(year, month, day)
	yesterday = system.date.addDays(today, -1)

	# === Turnos (0=Turno1, 1=Turno2, 2=Turno3) ===
	if dropDownPeriod in [0, 1, 2]:
		selectedShift = dropDownPeriod + 1  # 0→1, 1→2, 2→3

		if shift == 1:  # En Turno 1 (22:00-06:00)
			if selectedShift == 1:
				if hour >= 22:
					value = set_time(today, 22)
				else:  # 0-5
					value = set_time(yesterday, 22)
			elif selectedShift == 2:
				if hour >= 22:
					value = set_time(today, 6)
				else:
					value = set_time(yesterday, 6)
			elif selectedShift == 3:
				if hour >= 22:
					value = set_time(today, 14)
				else:
					value = set_time(yesterday, 14)

		elif shift == 2:  # En Turno 2 (06:00-14:00)
			if selectedShift == 1:
				value = set_time(yesterday, 22)
			elif selectedShift == 2:
				value = set_time(today, 6)
			elif selectedShift == 3:
				value = set_time(yesterday, 14)

		elif shift == 3:  # En Turno 3 (14:00-22:00)
			if selectedShift == 1:
				value = set_time(yesterday, 22)
			elif selectedShift == 2:
				value = set_time(today, 6)
			elif selectedShift == 3:
				value = set_time(today, 14)

	# === Día Actual: inicia con Turno 1 → 22:00 del día anterior ===
	# From 22:00 on, Turno 1 of the next production day has already started
	elif dropDownPeriod == 4:
		if hour >= 22:
			value = set_time(today, 22)
		else:
			value = set_time(yesterday, 22)

	# === Día Anterior: un día antes del Día Actual ===
	elif dropDownPeriod == 3:
		if hour >= 22:
			value = set_time(yesterday, 22)
		else:
			value = set_time(system.date.addDays(today, -2), 22)

	# === Semana: domingo anterior a las 22:00 (inicio del Turno 1 del lunes) ===
	elif dropDownPeriod == 5:
		dayOfWeek = system.date.getDayOfWeek(today)
		# getDayOfWeek: 1=Domingo, 2=Lunes, ..., 7=Sábado

		if dayOfWeek == 1:  # Domingo
			if hour >= 22:
				# Ya arrancó la nueva semana
				value = set_time(today, 22)
			else:
				# Aún semana anterior: domingo pasado a las 22
				previousSunday = system.date.addDays(today, -7)
				value = set_time(previousSunday, 22)
		elif dayOfWeek == 2:  # Lunes
			# Domingo anterior = ayer
			value = set_time(yesterday, 22)
		else:  # Martes(3) a Sábado(7)
			daysToMonday = dayOfWeek - 2
			monday = system.date.addDays(today, -daysToMonday)
			sundayBefore = system.date.addDays(monday, -1)
			value = set_time(sundayBefore, 22)

	# === Mes: día anterior al 1ro del mes a las 22:00 ===
	elif dropDownPeriod == 6:
		firstOfMonth = system.date.getDate(year, month, 1)
		dayBefore = system.date.addDays(firstOfMonth, -1)
		value = set_time(dayBefore, 22)

	return value

