"""
TablaSupervisor: reports WITHOUT supervisor signature (Status = 'Finalizado').

Version: 3.0.0
Changelog:
	2026-10-22 | William M. | v3.0.0 - Supervisor filter applied in dataReports
	2026-08-31 | Andres G. | v2.0.0 - Case-insensitive status filter + supervisor filter
"""
if value is None:
	return []

out = []
for row in value:
	status = str(row.get("Status", "") or "").strip().lower()
	if status != "finalizado":
		continue

	rowCells = {}
	for key in row:
		rowCells[key] = {"value": row[key]}
	out.append(rowCells)

return out

